/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Tests
 *   - Video navigation and wide cards remain reachable on desktop and narrow screens
 *   - Videos keeps loaded cards after a continuation fails and retries its cursor
 *   - Videos explains its error and empty states without requiring authentication
 *   - Video cards pause the shared player and navigation preserves its source and elapsed time
 *   - wide Video cards offer decorative hover previews without starting playback
 * @end-catalog */

import { trackFixtures } from './fixtures/catalog';
import { expectNoUnownedAxeViolations } from './support/accessibility';
import { installDeterministicAudio } from './support/deterministicAudio';
import { expect, test } from './support/test';

test('Video navigation and wide cards remain reachable on desktop and narrow screens', async ({ page }) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.goto('/finitude');
  await page.getByRole('link', { name: 'Video', exact: true }).click();
  await expect(page).toHaveURL(/\/finitude\/videos$/);
  const videos = page.getByRole('main').getByRole('region', { name: 'Video', exact: true });
  await expect(videos.getByRole('button', { name: 'Play First Light by Finitude Ensemble' })).toBeVisible();
  const screenshots = '/tmp/finitude-videos-page';
  await mkdir(screenshots, { recursive: true });

  for (const width of [1440, 768, 320]) {
    await page.setViewportSize({ width, height: 900 });
    await expect(page.getByRole('link', { name: 'Video', exact: true })).toBeVisible();
    const artwork = videos.locator('article [class*="artworkFrame"]').first();
    await expect(async () => {
      const bounds = await artwork.boundingBox();
      expect(bounds).not.toBeNull();
      expect(bounds!.width / bounds!.height).toBeCloseTo(16 / 9, 1);
      expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
    }).toPass();
    await page.screenshot({ path: `${screenshots}/populated-${width}.png`, fullPage: true, animations: 'disabled' });
  }
  await expectNoUnownedAxeViolations(page, 'videos-320');
  await page.reload();
  await expect(videos.getByRole('button', { name: 'Play First Light by Finitude Ensemble' })).toBeVisible();
});

test('Videos keeps loaded cards after a continuation fails and retries its cursor', async ({ page }) => {
  const cursor = '0123456789abcdef01234567';
  const older = { ...trackFixtures[0], id: 'older-video', title: 'Older Video' };
  const reads: Array<string | null> = [];
  let failing = true;
  await page.route('**/api/listener/v1/videos?**', (route) => {
    const after = new URL(route.request().url()).searchParams.get('cursor');
    reads.push(after);
    if (after && failing) return route.fulfill({ status: 503, json: { message: 'Unavailable' } });
    return route.fulfill({ json: after
      ? { items: [older], nextCursor: null }
      : { items: [trackFixtures[0]], nextCursor: cursor } });
  });
  await page.goto('/finitude/videos');
  const main = page.getByRole('main');
  await main.getByRole('button', { name: 'Load more', exact: true }).click();
  await expect(main.getByRole('alert')).toBeVisible();
  await expect(main.getByRole('button', { name: 'Play First Light by Finitude Ensemble' })).toBeVisible();
  failing = false;
  await main.getByRole('button', { name: 'Load more', exact: true }).click();
  await expect(main.getByRole('button', { name: 'Play Older Video by Finitude Ensemble' })).toBeVisible();
  await expect(main.getByRole('listitem')).toHaveCount(2);
  await expect(main.getByRole('button', { name: 'Load more', exact: true })).toHaveCount(0);
  expect(reads[0]).toBe(null);
  expect(reads.slice(1).every((value) => value === cursor)).toBe(true);
});

test('Videos explains its error and empty states without requiring authentication', async ({ page }) => {
  let failing = true;
  await page.route('**/api/listener/v1/videos?**', (route) => route.fulfill(failing
    ? { status: 503, json: { message: 'Unavailable' } }
    : { json: { items: [], nextCursor: null } }));
  await page.goto('/finitude/videos');
  const main = page.getByRole('main');
  await expect(main.getByRole('alert')).toBeVisible();
  failing = false;
  await main.getByRole('button', { name: 'Try again', exact: true }).click();
  await expect(main.getByText('No music is available in this section yet.')).toBeVisible();
  await expect(main.getByRole('listitem')).toHaveCount(0);
  await expect(main.getByRole('button', { name: 'Load more', exact: true })).toHaveCount(0);
});

test('Video cards pause the shared player and navigation preserves its source and elapsed time', async ({ api, page }) => {
  await installDeterministicAudio(page);
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('/finitude/videos');
  await page.getByRole('main').getByRole('button', { name: 'Play First Light by Finitude Ensemble' }).click();
  const player = page.getByRole('region', { name: 'Now playing', exact: true });
  await expect(player.getByRole('button', { name: 'Pause', exact: true })).toBeVisible();
  const media = await page.locator('video:not([data-video-preview])').elementHandle();
  expect(media).not.toBeNull();
  await media!.evaluate((element) => {
    const video = element as HTMLVideoElement;
    video.dataset.videosIdentity = 'original-player';
    video.currentTime = 4.5;
    video.dispatchEvent(new Event('timeupdate'));
  });
  // Clicking the current Video destination minimizes the theater and reveals its Pause card.
  await page.getByRole('link', { name: 'Video', exact: true }).click();
  await page.getByRole('main').getByRole('button', { name: 'Pause First Light', exact: true }).click();
  await expect(player.getByRole('button', { name: 'Play', exact: true })).toBeVisible();
  await page.getByRole('link', { name: 'Search', exact: true }).click();
  await page.getByRole('link', { name: 'Video', exact: true }).click();

  expect(await media!.evaluate((element) => {
    const video = element as HTMLVideoElement;
    return { connected: video.isConnected, identity: video.dataset.videosIdentity,
      time: video.currentTime, paused: video.paused, source: new URL(video.src).pathname };
  })).toEqual({ connected: true, identity: 'original-player', time: 4.5, paused: true,
    source: `/content/mediaTrack/stream/${trackFixtures[0].id}` });
  await expect(page.locator('video:not([data-video-preview])')).toHaveCount(1);
  expect(api.calls.some((call) => call.pathname === '/content/me/recently-played')).toBe(false);
});

test('wide Video cards offer decorative hover previews without starting playback', async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await page.goto('/finitude/videos');
  const card = page.getByRole('main').locator('article').first();
  await card.hover();
  const preview = card.locator('video[data-video-preview]');
  await expect(preview).toHaveAttribute('data-ready', 'true');
  expect(await preview.evaluate((element) => (element as HTMLVideoElement).muted)).toBe(true);
  await expect(page.getByRole('region', { name: 'Now playing', exact: true }).getByText('Nothing playing')).toBeVisible();
  await page.mouse.move(0, 0);
  await expect(preview).toHaveCount(0);
});
import { mkdir } from 'node:fs/promises';

